package main

import (
 "fmt"
 "strconv"
 "strings"
)
var offerSearch12115,offerProducts12115,offerList12115,offerTitle12115,offerPrice12115,offerStart12115,offerEnd12115 uintptr
var offerProductIDs12115 []int64
func showOfertasUI12115(){if !ensureDB(){return};currentModule="ofertas";clearContent();if e:=ensureOfertasConfig12115Schema();e!=nil{msgErr(e.Error());return};header("Ofertas","");add("STATIC","Produto",0,250,115,80,20,0);offerSearch12115=add("EDIT","",WS_BORDER|ES_AUTOHSCROLL,250,138,300,30,5101);add("BUTTON","Buscar",0,565,135,90,36,5102);offerProducts12115=add("LISTBOX","",WS_BORDER|WS_VSCROLL|LBS_NOTIFY|LBS_NOINTEGRALHEIGHT,250,180,620,190,5110);add("STATIC","Título da oferta",0,890,180,130,20,0);offerTitle12115=add("EDIT","OFERTA",WS_BORDER|ES_AUTOHSCROLL,890,203,300,30,5111);add("STATIC","Preço da oferta",0,890,245,130,20,0);offerPrice12115=add("EDIT","0,00",WS_BORDER|ES_AUTOHSCROLL,890,268,130,30,5112);add("STATIC","Início (AAAA-MM-DD)",0,890,310,160,20,0);offerStart12115=add("EDIT","",WS_BORDER|ES_AUTOHSCROLL,890,333,140,30,5113);add("STATIC","Fim",0,1045,310,60,20,0);offerEnd12115=add("EDIT","",WS_BORDER|ES_AUTOHSCROLL,1045,333,145,30,5114);add("BUTTON","SALVAR OFERTA",0,890,380,160,40,5120);add("BUTTON","Atualizar ativas",0,1060,380,150,40,5121);add("STATIC","Ofertas ativas — o preço promocional é usado automaticamente na consulta do produto.",0,250,405,850,24,0);offerList12115=add("LISTBOX","",WS_BORDER|WS_VSCROLL|LBS_NOINTEGRALHEIGHT,250,435,960,240,5130);loadOfferProducts12115();loadActiveOffersUI12115()}
func loadOfferProducts12115(){q:=strings.TrimSpace(getText(offerSearch12115));where:="1=1";if q!=""{x:=esc(q);where="(description LIKE '%"+x+"%' OR barcode LIKE '%"+x+"%')"};rows,e:=queryRows("SELECT id,COALESCE(barcode,''),description,printf('%.2f',price) FROM products WHERE "+where+" ORDER BY description LIMIT 200",4);if e!=nil{msgErr(e.Error());return};listReset(offerProducts12115);offerProductIDs12115=nil;listAdd(offerProducts12115,"CÓDIGO           PRODUTO                                      PREÇO NORMAL");for _,r:=range rows{id,_:=strconv.ParseInt(r[0],10,64);offerProductIDs12115=append(offerProductIDs12115,id);listAdd(offerProducts12115,fmt.Sprintf("%-16s %-44s R$ %s",r[1],clip(r[2],44),r[3]))}}
func selectedOfferProduct12115()int64{idx,_,_:=pSendMessageW.Call(offerProducts12115,LB_GETCURSEL,0,0);i:=int(idx)-1;if i<0||i>=len(offerProductIDs12115){return 0};return offerProductIDs12115[i]}
func saveOfferUI12115(){pid:=selectedOfferProduct12115();if pid==0{msg("Selecione o produto da oferta.");return};price:=parseF(getText(offerPrice12115));if price<=0{msg("Informe o preço da oferta.");return};if e:=saveOffer12115(0,pid,getText(offerTitle12115),price,getText(offerStart12115),getText(offerEnd12115),true);e!=nil{msgErr(e.Error());return};msg("Oferta salva.");loadActiveOffersUI12115()}
func loadActiveOffersUI12115(){rows,e:=activeOffers12115();if e!=nil{msgErr(e.Error());return};listReset(offerList12115);listAdd(offerList12115,"PRODUTO                                      NORMAL          OFERTA          INÍCIO       FIM");for _,r:=range rows{listAdd(offerList12115,fmt.Sprintf("%-44s R$ %10s   R$ %10s   %-12s %s",clip(r[1],44),r[2],r[3],r[4],r[5]))}}
func handleOfertasUI12115(id int)bool{switch id{case 5102:loadOfferProducts12115();case 5120:saveOfferUI12115();case 5121:loadActiveOffersUI12115();default:return false};return true}
